def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Extend each 6 along its NW-SE diagonal to the grid edges.
    for r, c in sixes:
        offset = c - r
        for rr in range(h):
            cc = rr + offset
            if 0 <= cc < w:
                out[rr][cc] = 6

    # Connect aligned pairs of 1s, without overwriting any 6s.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc) or dr == 0:
                continue
            steps = abs(dr)
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            for k in range(steps + 1):
                rr, cc = r1 + k * sr, c1 + k * sc
                if out[rr][cc] != 6:
                    out[rr][cc] = 1

    return out
